import{_ as t,a0 as o,w as d,s as c,ao as l,I as i,a1 as e,A as p,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 React 条件渲染中使用三元表达式和 “&&” | LCTT x X-CMD","titleTemplate":false,"description":"在 React 条件渲染中使用三元表达式和 “&&” | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 React 条件渲染中使用三元表达式和 “&&” | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 React 条件渲染中使用三元表达式和 “&&” | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180201 Conditional Rendering in React using Ternaries and","title":"在 React 条件渲染中使用三元表达式和 “&&”","tag":"201810","desc":""},"relativePath":"201810/20180201 Conditional Rendering in React using Ternaries and.md","filePath":"[post].md"}'),r={name:"201810/20180201 Conditional Rendering in React using Ternaries and.md"};function g(h,s,u,m,k,b){const n=o("Link");return d(),c("div",null,[s[20]||(s[20]=l(`<h1 id="在-react-条件渲染中使用三元表达式和" tabindex="-1">在 React 条件渲染中使用三元表达式和 “&amp;&amp;” <a class="header-anchor" href="#在-react-条件渲染中使用三元表达式和" aria-label="Permalink to “在 React 条件渲染中使用三元表达式和 “&amp;&amp;””">​</a></h1><p><img src="https://cdn-images-1.medium.com/max/2000/1*eASRJrCIVgsy5VbNMAzD9w.jpeg" alt=""></p><p>React 组件可以通过多种方式决定渲染内容。你可以使用传统的 <code>if</code> 语句或 <code>switch</code> 语句。在本文中，我们将探讨一些替代方案。但要注意，如果你不小心，有些方案会带来自己的陷阱。</p><h3 id="三元表达式-vs-if-else" tabindex="-1">三元表达式 vs if/else <a class="header-anchor" href="#三元表达式-vs-if-else" aria-label="Permalink to “三元表达式 vs if/else”">​</a></h3><p>假设我们有一个组件被传进来一个 <code>name</code> 属性。 如果这个字符串非空，我们会显示一个问候语。否则，我们会告诉用户他们需要登录。</p><p>这是一个只实现了如上功能的无状态函数式组件（SFC）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const MyComponent = ({ name }) =&gt; {</span></span>
<span class="line"><span>  if (name) {</span></span>
<span class="line"><span>    return (</span></span>
<span class="line"><span>      &lt;div className=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>        Hello {name}</span></span>
<span class="line"><span>      &lt;/div&gt;</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  return (</span></span>
<span class="line"><span>    &lt;div className=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>      Please sign in</span></span>
<span class="line"><span>    &lt;/div&gt;</span></span>
<span class="line"><span>  );</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>这个很简单但是我们可以做得更好。这是使用<ruby>三元运算符<rt>conditional ternary operator</rt></ruby>编写的相同组件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const MyComponent = ({ name }) =&gt; (</span></span>
<span class="line"><span>  &lt;div className=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>    {name ? \`Hello \${name}\` : &#39;Please sign in&#39;}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>请注意这段代码与上面的例子相比是多么简洁。</p><p>有几点需要注意。因为我们使用了箭头函数的单语句形式，所以隐含了<code>return</code> 语句。另外，使用三元运算符允许我们省略掉重复的 <code>&lt;div className=&quot;hello&quot;&gt;</code> 标记。</p><h3 id="三元表达式-vs" tabindex="-1">三元表达式 vs &amp;&amp; <a class="header-anchor" href="#三元表达式-vs" aria-label="Permalink to “三元表达式 vs &amp;&amp;”">​</a></h3><p>正如您所看到的，三元表达式用于表达 <code>if</code>/<code>else</code> 条件式非常好。但是对于简单的 <code>if</code> 条件式怎么样呢？</p><p>让我们看另一个例子。如果 <code>isPro</code>（一个布尔值）为真，我们将显示一个奖杯表情符号。我们也要渲染星星的数量（如果不是 0）。我们可以这样写。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const MyComponent = ({ name, isPro, stars}) =&gt; (</span></span>
<span class="line"><span>  &lt;div className=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>    &lt;div&gt;</span></span>
<span class="line"><span>      Hello {name}</span></span>
<span class="line"><span>      {isPro ? &#39;♨&#39; : null}</span></span>
<span class="line"><span>    &lt;/div&gt;</span></span>
<span class="line"><span>    {stars ? (</span></span>
<span class="line"><span>      &lt;div&gt;</span></span>
<span class="line"><span>        Stars:{&#39;☆&#39;.repeat(stars)}</span></span>
<span class="line"><span>      &lt;/div&gt;</span></span>
<span class="line"><span>    ) : null}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>请注意 <code>else</code> 条件返回 <code>null</code> 。 这是因为三元表达式要有“否则”条件。</p><p>对于简单的 <code>if</code> 条件式，我们可以使用更合适的东西：<code>&amp;&amp;</code> 运算符。这是使用 <code>&amp;&amp;</code> 编写的相同代码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const MyComponent = ({ name, isPro, stars}) =&gt; (</span></span>
<span class="line"><span>  &lt;div className=&quot;hello&quot;&gt;</span></span>
<span class="line"><span>    &lt;div&gt;</span></span>
<span class="line"><span>      Hello {name}</span></span>
<span class="line"><span>      {isPro &amp;&amp; &#39;♨&#39;}</span></span>
<span class="line"><span>    &lt;/div&gt;</span></span>
<span class="line"><span>    {stars &amp;&amp; (</span></span>
<span class="line"><span>      &lt;div&gt;</span></span>
<span class="line"><span>        Stars:{&#39;☆&#39;.repeat(stars)}</span></span>
<span class="line"><span>      &lt;/div&gt;</span></span>
<span class="line"><span>    )}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>没有太多区别，但是注意我们消除了每个三元表达式最后面的 <code>: null</code> （<code>else</code> 条件式）。一切都应该像以前一样渲染。</p><p>嘿！约翰得到了什么？当什么都不应该渲染时，只有一个 <code>0</code>。这就是我上面提到的陷阱。这里有解释为什么：</p>`,20)),i("p",null,[e(n,{href:"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Logical_Operators"},{default:p(()=>[...s[0]||(s[0]=[a("根据 MDN",-1)])]),_:1}),s[1]||(s[1]=a("，一个逻辑运算符“和”（也就是 ",-1)),s[2]||(s[2]=i("code",null,"&&",-1)),s[3]||(s[3]=a("）：",-1))]),s[21]||(s[21]=l(`<blockquote><p><code>expr1 &amp;&amp; expr2</code></p></blockquote><blockquote><p>如果 <code>expr1</code> 可以被转换成 <code>false</code> ，返回 <code>expr1</code>；否则返回 <code>expr2</code>。 如此，当与布尔值一起使用时，如果两个操作数都是 <code>true</code>，<code>&amp;&amp;</code> 返回 <code>true</code> ；否则，返回 <code>false</code>。</p></blockquote><p>好的，在你开始拔头发之前，让我为你解释它。</p><p>在我们这个例子里， <code>expr1</code> 是变量 <code>stars</code>，它的值是 <code>0</code>，因为 0 是假值，<code>0</code> 会被返回和渲染。看，这还不算太坏。</p><p>我会简单地这么写。</p><blockquote><p>如果 <code>expr1</code> 是假值，返回 <code>expr1</code> ，否则返回 <code>expr2</code>。</p></blockquote><p>所以，当对非布尔值使用 <code>&amp;&amp;</code> 时，我们必须让这个假值返回 React 无法渲染的东西，比如说，<code>false</code> 这个值。</p><p>我们可以通过几种方式实现这一目标。让我们试试吧。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{!!stars &amp;&amp; (</span></span>
<span class="line"><span>  &lt;div&gt;</span></span>
<span class="line"><span>    {&#39;☆&#39;.repeat(stars)}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>)}</span></span></code></pre></div><p>注意 <code>stars</code> 前的双感叹操作符（<code>!!</code>）（呃，其实没有双感叹操作符。我们只是用了感叹操作符两次）。</p><p>第一个感叹操作符会强迫 <code>stars</code> 的值变成布尔值并且进行一次“非”操作。如果 <code>stars</code> 是 <code>0</code> ，那么 <code>!stars</code> 会是 <code>true</code>。</p><p>然后我们执行第二个<code>非</code>操作，所以如果 <code>stars</code> 是 <code>0</code>，<code>!!stars</code> 会是 <code>false</code>。正好是我们想要的。</p><p>如果你不喜欢 <code>!!</code>，那么你也可以强制转换出一个布尔数比如这样（这种方式我觉得有点冗长）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{Boolean(stars) &amp;&amp; (</span></span></code></pre></div><p>或者只是用比较符产生一个布尔值（有些人会说这样甚至更加语义化）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{stars &gt; 0 &amp;&amp; (</span></span></code></pre></div><h4 id="关于字符串" tabindex="-1">关于字符串 <a class="header-anchor" href="#关于字符串" aria-label="Permalink to “关于字符串”">​</a></h4><p>空字符串与数字有一样的毛病。但是因为渲染后的空字符串是不可见的，所以这不是那种你很可能会去处理的难题，甚至可能不会注意到它。然而，如果你是完美主义者并且不希望 DOM 上有空字符串，你应采取我们上面对数字采取的预防措施。</p><h3 id="其它解决方案" tabindex="-1">其它解决方案 <a class="header-anchor" href="#其它解决方案" aria-label="Permalink to “其它解决方案”">​</a></h3><p>一种可能的将来可扩展到其他变量的解决方案，是创建一个单独的 <code>shouldRenderStars</code> 变量。然后你用 <code>&amp;&amp;</code> 处理布尔值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const shouldRenderStars = stars &gt; 0;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>return (</span></span>
<span class="line"><span>  &lt;div&gt;</span></span>
<span class="line"><span>    {shouldRenderStars &amp;&amp; (</span></span>
<span class="line"><span>      &lt;div&gt;</span></span>
<span class="line"><span>        {&#39;☆&#39;.repeat(stars)}</span></span>
<span class="line"><span>      &lt;/div&gt;</span></span>
<span class="line"><span>    )}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>之后，在将来，如果业务规则要求你还需要已登录，拥有一条狗以及喝淡啤酒，你可以改变 <code>shouldRenderStars</code> 的得出方式，而返回的内容保持不变。你还可以把这个逻辑放在其它可测试的地方，并且保持渲染明晰。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const shouldRenderStars = </span></span>
<span class="line"><span>  stars &gt; 0 &amp;&amp; loggedIn &amp;&amp; pet === &#39;dog&#39; &amp;&amp; beerPref === &#39;light\`;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>return (</span></span>
<span class="line"><span>  &lt;div&gt;</span></span>
<span class="line"><span>    {shouldRenderStars &amp;&amp; (</span></span>
<span class="line"><span>      &lt;div&gt;</span></span>
<span class="line"><span>        {&#39;☆&#39;.repeat(stars)}</span></span>
<span class="line"><span>      &lt;/div&gt;</span></span>
<span class="line"><span>    )}</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>);</span></span></code></pre></div><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>我认为你应该充分利用这种语言。对于 JavaScript，这意味着为 <code>if/else</code> 条件式使用三元表达式，以及为 <code>if</code> 条件式使用 <code>&amp;&amp;</code> 操作符。</p><p>我们可以回到每处都使用三元运算符的舒适区，但你现在消化了这些知识和力量，可以继续前进 <code>&amp;&amp;</code> 取得成功了。</p><hr><p>作者简介：</p>`,30)),i("p",null,[s[5]||(s[5]=a("美国运通工程博客的执行编辑 ",-1)),e(n,{href:"http://aexp.io"},{default:p(()=>[...s[4]||(s[4]=[a("http://aexp.io",-1)])]),_:1}),s[6]||(s[6]=a(" 以及 @AmericanExpress 的工程总监。MyViews !== ThoseOfMyEmployer.",-1))]),s[22]||(s[22]=i("hr",null,null,-1)),i("p",null,[s[8]||(s[8]=a("via: ",-1)),e(n,{href:"https://medium.freecodecamp.org/conditional-rendering-in-react-using-ternaries-and-logical-and-7807f53b6935"},{default:p(()=>[...s[7]||(s[7]=[a("https://medium.freecodecamp.org/conditional-rendering-in-react-using-ternaries-and-logical-and-7807f53b6935",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("作者：",-1)),e(n,{href:"https://medium.freecodecamp.org/@donavon"},{default:p(()=>[...s[9]||(s[9]=[a("Donavon West",-1)])]),_:1}),s[13]||(s[13]=a(" 译者：",-1)),e(n,{href:"https://github.com/GraveAccent"},{default:p(()=>[...s[10]||(s[10]=[a("GraveAccent",-1)])]),_:1}),s[14]||(s[14]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[16]||(s[16]=[a("Linux中国",-1)])]),_:1}),s[19]||(s[19]=a(" 荣誉推出",-1))])])}const y=t(r,[["render",g]]);export{C as __pageData,y as default};
